          "comment": "Didn't run badly on slower-than-ideal ground last time; worth a second look",
          "spotlight": "Veteran who gained four of his 14 wins here (one over C&D); ran much better than eventual 22l defeat might suggest on slower-than-ideal ground at Cartmel (2m1f good to soft) a fortnight ago; worth a second look here, even from 4lb out of the weights.",
          "quotes": [
            {
              "date": "2018-07-06",
              "horse": "Sword Of Fate",
              "horse_id": "hrs_9396618",
              "race": "Betfair #racingstaff Week Novices' Handicap Chase",
              "race_id": "rac_9161464",
              "course": "Newton Abbot",
              "course_id": "crs_1014",
              "distance_f": "21",
              "distance_y": "4616",
              "quote": "Sword Of Fate had to come here after his Stratford win the other night as it was the last time he would have been off his old mark as he is due to go up 6lb. He has now had two runs in four days so he will have a little break and be back in three weeks or so - Tom Lacey, trainer."
            },
            {
              "date": "2017-10-17",
              "horse": "Sword Of Fate",
              "horse_id": "hrs_9396618",
              "race": "Central Roofing South Wales \"National Hunt\" Novices' Hurdle",
              "race_id": "rac_8932001",
              "course": "Worcester",
              "course_id": "crs_2626",
              "distance_f": "16",
              "distance_y": "3520",
              "quote": "We did not really want to run Sword Of Fate so quickly after his win here last week, but this looked too good an opportunity to miss. He wants this ground and when the rain comes he will be off on his holidays until next spring - Tom Lacey, trainer."
            },
            {
              "date": "2017-10-12",
              "horse": "Sword Of Fate",
              "horse_id": "hrs_9396618",
              "race": "7bets4free.com EBF \"National Hunt\" Novices' Hurdle (Qualifier)",
              "race_id": "rac_8897889",
              "course": "Worcester",
              "course_id": "crs_2626",
              "distance_f": "16",
              "distance_y": "3520",
              "quote": "Sword Of Fate was weak last year, but he loved that ground and we like him - Tom Lacey, trainer."
            }
          ],
