          "comment": "Seemed to have turned a corner when close third of four on last month's stable debut",
          "spotlight": "Ended last season in very poor form for Nigel Twiston-Davies but seemed to have turned a corner when close third of four (just behind Jakana) at Hexham (2m4f, good) for new stable three weeks ago, where a last-flight error might have cost him the race; has a fighting chance here; tongue-tie added.",
          "quotes": [
            {
              "date": "2023-12-17",
              "horse": "Tommie Gun",
              "horse_id": "hrs_34470688",
              "race": "Sponsorship Branding @ signsolutions.org Maiden Hurdle (GBB Race)",
              "race_id": "rac_11106680",
              "course": "Southwell",
              "course_id": "crs_1586",
              "distance_f": "16",
              "distance_y": "3482",
              "quote": "Graham and Alison [Jelley, owners] have been supremely patient with Tommie Gun. He had loads of sinus troubles and it wasn't an easy problem to fix. He basically always had a runny nose but now they've fixed that, so hopefully he can repay them with all that support he's been given. He's done a lot of jumping and had been a little bit clumsy at home. It was nice to come here over the fixed brush hurdles as it helped him jump neatly and accurately - Sam Twiston-Davies, speaking on Sky Sports Racing."
            }
          ],
