          "comment": "Has modest strike-rate over hurdles but is not a forlorn hope off career-low mark",
          "spotlight": "Ex-Irish 8yo with very modest 1-24 strike-rate over hurdles; now 8lb lower than for big-odds second at Carlisle (2m1f, soft) in October, though, and might have needed his run here last month; not a forlorn hope.",
