          "comment": "Form dipped after he landed a good prize in October; tries a new trip today; bit to prove",
          "spotlight": "Suffered alarming dip in form after collecting good prize at Kelso (2m1f, good) in October and, following a break, was only fourth best on merit when modest third here (2m; first-time cheekpieces) last month; had wind surgery soon afterwards and now tries a new trip; others have less to prove.",
          "quotes": [
            {
              "date": "2024-10-06",
              "horse": "Breizh River",
              "horse_id": "hrs_33081678",
              "race": "Ray & Anita Green Chasing 500 Winners Handicap Chase (Registered As The Simply Ned) (GBB Race)",
              "race_id": "rac_11384087",
              "course": "Kelso",
              "course_id": "crs_702",
              "distance_f": "17",
              "distance_y": "3754",
              "quote": "Breizh River is a cracking horse. He's been very lightly raced and we're just going to target him at certain races throughout the season. He won't take a lot of racing because he's only six and is quite backward in his mind, but he's obviously very tough. He'll have a break now and we'll aim him at the Southam Handicap Chase over two and a half miles at Cheltenham's November meeting. That was always the plan and we know he wants further - Paul Robson, trainer."
            }
          ],
