          "comment": "Game front-runner who was close third over C&D last month; considered off same mark today",
          "spotlight": "Returned to form with game win at Kelso (2m7f, good) in April and gave it a good shot from the front when close third (just behind Wasdell Dundalk) over C&D (good) last month; one to consider.",
          "quotes": [
            {
              "date": "2025-04-07",
              "horse": "Half Shot",
              "horse_id": "hrs_17274110",
              "race": "Ashleybank Investments Reg And Betty Tweedie Handicap Chase (GBB Race)",
              "race_id": "rac_11575733",
              "course": "Kelso",
              "course_id": "crs_702",
              "distance_f": "23.5",
              "distance_y": "5156",
              "quote": "Half Shot is a good old yardstick who keeps coming back and he wins his couple every year. When the second horse came to him he battled away well - Brian Hughes, jockey, speaking to Racing TV."
            },
            {
              "date": "2023-11-30",
              "horse": "Half Shot",
              "horse_id": "hrs_17274110",
              "race": "James And Gloria Roche Handicap Chase",
              "race_id": "rac_11090495",
              "course": "Musselburgh",
              "course_id": "crs_416",
              "distance_f": "23.5",
              "distance_y": "5198",
              "quote": "Half Shot was weighted to carry 8st 5lb at Newcastle (in the Rehearsal, with Shishkin compressing the weights), so we thought we'd come here. He won that well and jumped class there. I thought it was a great ride from Brian Hughes. I think this horse has got a good race in him, he's very consistent and genuine. He'll get a hike for that, so we'll have to look at better races. He ran in the Scottish National last season, so we could look at that again in the spring - Iain Jardine, trainer."
            }
          ],
