          "comment": "Four-time C&D winner; still on a good mark after last month's C&D second; likely contender",
          "spotlight": "Four-time C&D winner; returned from break with very poor hurdle run in May but quickly got back in the groove in C&D (good) chase last month, keeping on well to snatch second from Half Shot close home; still on a good mark; might be the answer.",
