          "comment": "Dual C&D winner last summer and posted 50-1 success at Punchestown festival in April",
          "spotlight": "Won twice over C&D (good) last summer and took form to whole new level when posting 50-1 success in 25-runner series final at Punchestown festival (2m3f, yielding) in April; held off new mark twice since but drops in grade today and the return to this track is an obvious plus.",
