          "comment": "Irish raider; well handicapped on old form and Sean Bowen is a good booking",
          "spotlight": "Returned from layoff with low-key run in May and was brought down mid-race at Kilbeggan last month but this Irish raider is well handicapped on old form and the booking of Sean Bowen catches the eye.",
