          "comment": "Plenty of hope for 1m3f on this handicap debut but a marked advance is needed",
          "spotlight": "Won two minor races on the Kempton AW (1m/1m3f) to start career; her second 1m2f Listed run was better than the first and there is plenty of hope for 1m3f on this handicap debut, but a marked advance is needed.",
          "quotes": [
            {
              "date": "2024-08-20",
              "horse": "Trad Jazz",
              "horse_id": "hrs_43131648",
              "race": "Unibet Zero% Mission \"Confined\" Restricted Maiden Fillies' Stakes (No More Than 3 Runs) (GBB Race)",
              "race_id": "rac_11350664",
              "course": "Kempton (AW)",
              "course_id": "crs_28054",
              "distance_f": "8",
              "distance_y": "1760",
              "quote": "I thought Trad Jazz would run well. We don't turn the screw on these 2yos at home and we're learning as we go along this season with it being our first year, so a lot of that was natural ability, and she was professional. She's appreciated the surface and the mile. What she's beat I don't know, but it was a nice performance. We're treating the juveniles as 3yo types. They're horses for the future, so every run is progressive. She's going to come on a lot for that run - James Owen, speaking on Racing TV."
            }
          ],
          "stable_tour": [
            {
              "quote": "She's a lovely filly who won on her debut at Kempton. I was going to run her at the back end in a Newmarket Listed race but she just wasn't quite right, so we decided to give her a break and she's done very well back at the stud. She's from a real staying family and I think she can make up into a really nice three-year-old. 01-01-25"
            }
          ],
