          "owner": "Sheikh Juma Dalmook Al Maktoum",
          "owner_id": "own_804908",
          "prev_trainers": [],
          "prev_owners": [],
          "comment": "Cornwallis third; drops back in trip/class but has a fairly tough mark to overcome",
          "spotlight": "Progressive in three starts over 5f on turf last season, running well in the Cornwallis the final time; failed to beat a rival in 6f Group 2 at Haydock on reappearance; drops back in trip/class but has a fairly tough mark to overcome.",
          "quotes": [
            {
              "date": "2024-09-13",
              "horse": "Kullazain",
              "horse_id": "hrs_44481318",
              "race": "Madri Excepcional EBF Maiden Stakes (GBB Race)",
              "race_id": "rac_11372218",
              "course": "Sandown",
              "course_id": "crs_1404",
              "distance_f": "5",
              "distance_y": "1110",
              "quote": "We liked Kullazain at the sales but he was a bit of a baby. He had sore shins and he was a bit behind so we've given him time, but we learnt a bit at Ripon and he was impressive here. He'll be better next year. He likes soft ground so I suppose we could think about something like the Cornwallis or a Listed race at Chantilly at the end of October - James Tate, trainer."
            }
          ],
          "stable_tour": [
            {
              "quote": "I went into this season thinking he was a really good horse and he certainly looked one based on his three runs last year, when he won and was third twice. He should be stronger and better this year. The ground was too quick for him at Haydock in the Group 2 Sandy Lane Stakes first time out - he probably didn't get the 6f anyway and on top of that he probably needed the run. He's ready to go again but the rain gods haven't been kind to him and we're going to have to wait a bit. I'm sure he's one to look out for in the autumn if it doesn't rain in the short term. 09-07-25"
            }
          ],
