          "spotlight": "Won a bumper on turf here in 2021; first win since was at Lingfield (2m, good) in just her fourth handicap, doing it smoothly from off the pace under Liam Wright despite an absence of more than three years; it's five days this time but she has form on Tapeta and has to be in serious calculations.",
