          "comment": "No joy yet for James Owen; also less convincing here, in blinkers and over 2m on Flat",
          "spotlight": "Beaten favourite (Flat/hurdles) in his first three races for James Owen, before a modest show at Carlisle eight days ago; effective on Newcastle Tapeta but less convincing here, in blinkers and over 2m on Flat.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "A nice horse who had kissing spines and has been operated on. There were a few times last year when he went to win his races and his head came up. We were wondering whether he was thinking about the game, but we found out he had severe back problems. He's back in now and working away well and should be ready to run in a month. We think a lot of him and I reckon he could be all right. 03-04-24"
            }
          ],
