          "comment": "Looks vulnerable off current mark unless the new tongue-tie brings him on",
          "spotlight": "Juvenile hurdle winner who has finished third in both his handicaps, beaten about 3l and 10l; looks vulnerable off current mark unless the new tongue-tie brings him on.",
          "quotes": [
            {
              "date": "2024-07-14",
              "horse": "Battle Of Omdurman",
              "horse_id": "hrs_37052330",
              "race": "Malcom Wheeler 70th Birthday Celebration Juvenile Hurdle (GBB Race)",
              "race_id": "rac_11313432",
              "course": "Stratford",
              "course_id": "crs_1742",
              "distance_f": "16.5",
              "distance_y": "3590",
              "quote": "Battle Of Omdurman won really well. He's obviously taken to hurdling. He made a little bit of an error at the first, as he was a bit green, but after that he got stuck in, which was really nice. He's got a bit of growing and strengthening up to do but it's exciting. We'll see how we go. We haven't made a plan as you just don't know with these juveniles - Deborah Cole, trainer."
            }
          ],
          "stable_tour": [
            {
              "quote": "He has a nice pedigree and was an expensive enough foal, then a less-expensive yearling. He's a fine, big, good-looking horse and works well and I've been looking forward to getting him going. I expected him to run a nice race on his debut at Kempton last week, although it was a competitive contest and I thought he'd improve for the run, and he ran okay considering how green he was. He started over a mile and I suspect he's going to want a bit further next year. 12-09-23"
            }
          ],
