          "comment": "Plenty of Flat/hurdle wins; fourth on chase debut here and this longer trip is worth a go",
          "spotlight": "Plenty of Flat/hurdle wins, mostly in Jersey; made a belated chase debut here 12 days ago (2m3f) but took to it pretty well and stayed on for fourth (beaten under 10l); unraced over this far but it's worth a go.",
