          "comment": "Likeable veteran, won off 2lb higher in April, likes it here and dangerous to dismiss",
          "spotlight": "Likeable veteran is a three-time C&D winner; showed he retains ability when winning off 66 at Musselburgh (5f, good) in April; 2lb lower here and ran creditably in a much stronger race than this on his last run over this C&D in May; dangerous to dismiss on his 100th start.",
          "quotes": [
            {
              "date": "2025-04-13",
              "horse": "Only Spoofing",
              "horse_id": "hrs_7661822",
              "race": "Sky Bet Acca Freeze Handicap",
              "race_id": "rac_11574849",
              "course": "Musselburgh",
              "course_id": "crs_416",
              "distance_f": "5",
              "distance_y": "1101",
              "quote": "We had this planned a long way out and we had the best jockey in the north of Britain on - he doesn't panic. We were going to retire Only Spoofing last year but he's not one for that just yet. He's a tough nut and doesn't think he's 11 - Kevin Coleman, trainer."
            },
            {
              "date": "2021-05-15",
              "horse": "Only Spoofing",
              "horse_id": "hrs_7661822",
              "race": "Bellinter Handicap",
              "race_id": "rac_10201178",
              "course": "Navan",
              "course_id": "crs_5018",
              "distance_f": "5",
              "distance_y": "1100",
              "quote": "Only Spoofing loves this track and trip. He cut out at Naas last day and back to five today suited him - Kevin Coleman, trainer."
            },
            {
              "date": "2019-07-26",
              "horse": "Only Spoofing",
              "horse_id": "hrs_7661822",
              "race": "Neptune Investment Management Supports Child Bereavement UK Handicap",
              "race_id": "rac_9541610",
              "course": "Ascot",
              "course_id": "crs_52",
              "distance_f": "5",
              "distance_y": "1100",
              "quote": "Only Spoofing is improving and came here in good form. He was great today and I think he could win a big one before the end of the year - Kieran O'Neill, jockey."
            },
            {
              "date": "2018-09-08",
              "horse": "Only Spoofing",
              "horse_id": "hrs_7661822",
              "race": "Troytown Bar Handicap",
              "race_id": "rac_9245080",
              "course": "Navan",
              "course_id": "crs_5018",
              "distance_f": "5",
              "distance_y": "1100",
              "quote": "He can be very buzzy and went to the start early. Sean (Davis) had ridden him before and gave him a very brave ride. He's great value for his 7lb claim and you'd never think he was a claimer watching that ride. I'd imagine Only Spoofing will be coming back to Ireland before the end of the season - Tim Hogg, assistant to Jedd O'Keeffe, trainer of Only Spoofing."
            }
          ],
