          "comment": "Won off 5lb lower at Bellewstown in April, below par back on Flat latest, others preferred",
          "spotlight": "Won a 0-60 off 5lb lower over at Bellewstown (1m4f, good) in April and followed up in a Tipperary maiden hurdle in May; failed to fire back on the Flat at Leopardstown last month; others make more appeal.",
