          "comment": "Below best in chasing and hurdle starts recently; takes a marked step back in trip here",
          "spotlight": "Below his best in chasing and hurdle starts recently; beaten 22l at Bellewstown over timber when last seen earlier this month (3m, good); last win came at Downpatrick in a beginners' chase in April last year (2m7f, good); takes a marked step back in trip here and needs to find his form again.",
