          "comment": "C&D winner; won off this mark in 2023; only seen 3 times since and tailed off latest",
          "spotlight": "C&D winner who won off this mark at Listowel in 2023; only seen three times since and tailed off on the back of a 420-day absence at Punchestown last month; should find out more here but looks risky.",
          "quotes": [
            {
              "date": "2023-09-20",
              "horse": "Ballyglass Beauty",
              "horse_id": "hrs_28110383",
              "race": "Devon Inn Hotel Handicap Hurdle",
              "race_id": "rac_11049883",
              "course": "Listowel",
              "course_id": "crs_4940",
              "distance_f": "24",
              "distance_y": "5280",
              "quote": "We said we'd take a chance of getting in the bottom of a handicap off a light weight with Ballyglass Beauty. It was a classy-looking race but the horses coming out helped. I said to Charlie to get him settled, creep away and ride him to get a bit of money and it worked out lovely. He's a Westerner and most of them handle heavy. He's a small, light type, so we thought we'd get away with soft. He stays and is consistent - Liam Cusack, trainer."
            },
            {
              "date": "2022-09-02",
              "horse": "Ballyglass Beauty",
              "horse_id": "hrs_28110383",
              "race": "Celebrating The Life Of Sean Daly Memorial Handicap Hurdle",
              "race_id": "rac_10664511",
              "course": "Kilbeggan",
              "course_id": "crs_5278",
              "distance_f": "24.5",
              "distance_y": "5380",
              "quote": "Ballyglass Beauty had a lovely run here the last day and the extra distance helped him today. He was quite keen when he came and was a bit of a runaway. He might go to Listowel - Liam Cusack, trainer."
            }
          ],
